import {bookFinishes,cleanBookFinish} from './book-finish.js';
import {coverOptions,coverExample} from './cover-catalog.js';
export function initBookShowcase({onPreview,onCreate,onCatalog}){
 const section=document.createElement('section');section.className='book-showcase section-width';section.id='livros-design';section.setAttribute('aria-labelledby','book-showcase-title');section.innerHTML='<div class="book-showcase-copy"><p class="book-showcase-label">A coleção Papel & Cacau</p><h2 id="book-showcase-title">Sua história.<br>Um livro só seu.</h2><p class="book-showcase-intro">A foto que merece uma capa. A voz que dá vontade de ouvir de novo. Um álbum digital para abrir, folhear e sentir por perto.</p><div class="showcase-finishes" role="group" aria-label="Experimentar encadernações"></div><p class="showcase-material-name" aria-live="polite"></p><div class="showcase-features"><span>Capa com textura</span><span>Título metalizado</span><span>Fotos e voz de vocês</span></div><button class="button primary showcase-create">Fazer um livro assim ↗</button><button class="showcase-catalog">Ver as capas da coleção →</button><small>Presente digital em 3D. Não é um livro físico.</small></div><div class="book-showcase-art"><div class="showcase-stage" aria-label="Álbum digital em Three.js"><p class="showcase-loading" role="status">Preparando o seu álbum…</p></div><div class="showcase-view-controls"><button class="showcase-open" type="button">Folhear o exemplo</button><button class="showcase-fit" type="button">Ver inteiro</button><button class="showcase-recipient" type="button">Abrir como presente ↗</button></div><p class="showcase-view-note">Arraste para girar. Toque para aproximar um detalhe.</p></div>';
 document.querySelector('#colecao').before(section);const navLink=document.createElement('a');navLink.href='#livros-design';navLink.textContent='Livros';document.querySelector('.nav-wrap nav').append(navLink);let material='cocoa',reader=null,ready=null,opened=false;const cover=()=>({...coverOptions('casamento','livro')[0],bookFinish:cleanBookFinish({material,foil:'gold',ribbon:true})});const data=()=>{const example=coverExample(cover());return {...example,recipient:'Lia & Rafa',stationeryDesign:{...example.stationeryDesign,title:'O começo de tudo.',closing:'Para guardar. Para sempre lembrar.'},appearance:{...example.appearance,scene:'studio'}};};
 async function ensure(){if(reader)return reader;if(!ready){ready=import('./book.js').then(async({createBook})=>{reader=await createBook(section.querySelector('.showcase-stage'),data());section.querySelector('.showcase-loading').hidden=true;for(let i=0;i<2;i++)section.querySelector('.showcase-stage canvas').dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft'}));return reader;}).catch(()=>{section.querySelector('.showcase-loading').textContent='Toque em “Abrir como presente” para conhecer o exemplo.';});}return ready;}
 function render(){section.querySelectorAll('[data-showcase-finish]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.showcaseFinish===material)));section.querySelector('.showcase-material-name').textContent=bookFinishes[material].label+' · acabamento champagne';reader?.set(data());}
 for(const [id,finish]of Object.entries(bookFinishes)){const button=document.createElement('button');button.type='button';button.dataset.showcaseFinish=id;button.setAttribute('aria-label','Experimentar '+finish.label);button.style.setProperty('--finish-color',finish.color);button.style.setProperty('--finish-texture','url(assets/book-'+finish.kind+'-albedo.webp)');button.innerHTML='<span></span>';button.addEventListener('click',async()=>{material=id;render();await ensure();reader?.set(data());});section.querySelector('.showcase-finishes').append(button);}
 const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){ensure();observer.disconnect();}},{rootMargin:'150px'});observer.observe(section);
 section.querySelector('.showcase-open').addEventListener('click',async()=>{await ensure();opened=!opened;reader?.open(opened);section.querySelector('.showcase-open').textContent=opened?'Ver a capa':'Folhear o exemplo';});section.querySelector('.showcase-fit').addEventListener('click',()=>reader?.resetView());section.querySelector('.showcase-recipient').addEventListener('click',()=>onPreview(data()));section.querySelector('.showcase-create').addEventListener('click',()=>onCreate(cover()));section.querySelector('.showcase-catalog').addEventListener('click',()=>onCatalog('casamento','livro'));render();window.__bookShowcase={snapshot:()=>reader?.snapshot(),getData:data};return {section};
}
